// SynthyBoy - MPC overlay: the proportional UI font (Titillium Web SemiBold, SIL OFL 1.1) as a signed distance field atlas (sdf_font_data.h, generated by scripts/gen-overlay-font.py): the
// glyph lookup, the text metrics (width, the cut of a long text with an ellipsis), the layout of a string into glyph quads, and the coverage of a pixel. The GPU helper draws the quads with
// a fragment shader that makes exactly the coverage of `coverage` (clamp (0.5 + d * size / kEm, 0, 1)); the CPU reference (scene_cpu.h, draw.h) samples the same atlas bilinearly.
// Copyright (C) 2026 Safian Szabolcs
// SPDX-License-Identifier: AGPL-3.0-or-later
#pragma once

#include <algorithm>
#include <cmath>
#include <cstddef>
#include <cstdint>
#include <cstring>

#include "sdf_font_data.h"

namespace synthyboy_mpc { namespace overlay { namespace sdf {

constexpr uint32_t kEllipsis = 0x2026u, kReplacement = '?';

/** The next code point of a UTF-8 string (`p` moves on; a broken sequence gives one '?' and skips one byte). */
inline uint32_t nextCodepoint (const char*& p, const char* end) noexcept
{
    const unsigned char c = static_cast<unsigned char> (*p++);
    if (c < 0x80u)
        return c;
    int extra = (c >= 0xf0u && c < 0xf8u) ? 3 : (c >= 0xe0u) ? 2 : (c >= 0xc0u) ? 1 : -1;
    if (extra < 0 || end - p < extra)
        return kReplacement;
    uint32_t cp = c & (0x3fu >> extra);
    for (int i = 0; i < extra; ++i)
    {
        const unsigned char d = static_cast<unsigned char> (p[i]);
        if ((d & 0xc0u) != 0x80u)
            return kReplacement;
        cp = (cp << 6) | (d & 0x3fu);
    }
    p += extra;
    return cp;
}

inline const GlyphData* find (uint32_t cp) noexcept
{
    int lo = 0, hi = kNumGlyphs - 1;
    while (lo <= hi)
    {
        const int mid = (lo + hi) / 2;
        if (kGlyphs[mid].cp == cp)
            return &kGlyphs[mid];
        if (kGlyphs[mid].cp < cp)
            lo = mid + 1;
        else
            hi = mid - 1;
    }
    return nullptr;
}
/** The glyph of a code point; '?' when the font has none (never null: '?' is in the atlas). */
inline const GlyphData& glyph (uint32_t cp) noexcept
{
    if (const GlyphData* g = find (cp))
        return *g;
    return *find (kReplacement);
}

/** The width in pixels of the string at `size` pixels per em (`tracking` em extra after every glyph). */
inline float textWidth (const char* s, int n, float size, float tracking = 0.0f) noexcept
{
    float w = 0.0f;
    const char* p = s;
    const char* end = s + n;
    while (p < end)
        w += (glyph (nextCodepoint (p, end)).advance + tracking) * size;
    return w;
}
inline float textWidth (const char* s, float size, float tracking = 0.0f) noexcept { return textWidth (s, static_cast<int> (std::strlen (s)), size, tracking); }

/** Writes into out[cap] (zero terminated) as much of the string as fits in `maxWidth` pixels; when it has to be cut, the end is "…" (the part kept is the longest that fits together with
    the ellipsis). Returns the width of the result. A string that fits is copied whole. */
inline float fitText (const char* s, float size, float maxWidth, char* out, int cap, float tracking = 0.0f) noexcept
{
    const int n = static_cast<int> (std::strlen (s));
    const float full = textWidth (s, n, size, tracking);
    if (full <= maxWidth || cap < 5)
    {
        const int c = std::min (n, cap - 1);
        std::memcpy (out, s, static_cast<size_t> (c));
        out[c] = '\0';
        return full;
    }
    const float ell = (glyph (kEllipsis).advance + tracking) * size;
    const char* p = s;
    const char* end = s + n;
    const char* keep = s;
    float w = 0.0f;
    while (p < end)
    {
        const char* q = p;
        const float a = (glyph (nextCodepoint (q, end)).advance + tracking) * size;
        if (w + a + ell > maxWidth)
            break;
        w += a;
        p = q;
        keep = p;
    }
    const int c = static_cast<int> (std::min<ptrdiff_t> (keep - s, cap - 4));
    std::memcpy (out, s, static_cast<size_t> (c));
    out[c] = '\xe2'; out[c + 1] = '\x80'; out[c + 2] = '\xa6'; out[c + 3] = '\0';   // U+2026
    return w + ell;
}

/** One glyph placed: the screen rectangle of its bitmap (pixels) and the atlas texel rectangle (u0, v0, u1, v1, in atlas pixels). */
struct Quad { float x0, y0, x1, y1, u0, v0, u1, v1; };

/** Calls fn (const Quad&) for every glyph that has an outline of the string: the pen starts at (x, baseline). */
template <class Fn>
void layout (const char* s, int n, float x, float baseline, float size, float tracking, Fn fn)
{
    const float k = size / static_cast<float> (kEm);
    float pen = x;
    const char* p = s;
    const char* end = s + n;
    while (p < end)
    {
        const GlyphData& g = glyph (nextCodepoint (p, end));
        if (g.w > 0)
        {
            Quad q;
            q.x0 = pen + g.left * k;
            q.y0 = baseline - g.top * k;
            q.x1 = q.x0 + static_cast<float> (g.w) * k;
            q.y1 = q.y0 + static_cast<float> (g.h) * k;
            q.u0 = static_cast<float>(g.x); q.v0 = static_cast<float>(g.y); q.u1 = static_cast<float>(g.x + g.w); q.v1 = static_cast<float>(g.y + g.h);
            fn (q);
        }
        pen += (g.advance + tracking) * size;
    }
}

/** The atlas value (0 .. 1) at the texel coordinates (u, v) (pixel centres at i + 0.5), bilinear, clamped to the atlas. */
inline float atlasSample (float u, float v) noexcept
{
    u -= 0.5f;
    v -= 0.5f;
    const float fu = std::floor (u), fv = std::floor (v);
    const int x0 = static_cast<int> (fu), y0 = static_cast<int> (fv);
    const float tx = u - fu, ty = v - fv;
    auto at = [] (int x, int y) { x = std::min (std::max (x, 0), kAtlasW - 1); y = std::min (std::max (y, 0), kAtlasH - 1); return static_cast<float> (kAtlas[y * kAtlasW + x]) * (1.0f / 255.0f); };
    const float a = at (x0, y0), b = at (x0 + 1, y0), c = at (x0, y0 + 1), d = at (x0 + 1, y0 + 1);
    return (a + (b - a) * tx) + ((c + (d - c) * tx) - (a + (b - a) * tx)) * ty;
}

/** The coverage of a pixel from the atlas value `v`: the distance d = (v - 0.5) * 2 * kSpread atlas pixels, scaled to the screen by size / kEm. */
inline float coverage (float v, float size) noexcept
{
    const float c = 0.5f + (v - 0.5f) * 2.0f * static_cast<float> (kSpread) * size / static_cast<float> (kEm);
    return c < 0.0f ? 0.0f : (c > 1.0f ? 1.0f : c);
}

/** The height of the capital letters and the x height at `size`, the baseline row for a text whose capitals are centred on `centre` (row). */
inline float capHeight (float size) noexcept { return kCapHeight * size; }
inline float baselineForCentre (float centre, float size) noexcept { return centre + 0.5f * kCapHeight * size; }

}}} // namespace synthyboy_mpc::overlay::sdf
